import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

export async function users_table_exists(ctx: AssertionContext): Promise<AssertionResult> {
  const result = await ctx.pg.query(
    "SELECT count(*) AS n FROM information_schema.tables WHERE table_schema = 'app' AND table_name = 'users'",
  );
  const count = Number(result.rows[0]?.n ?? 0);
  const passed = count === 1;
  return {
    passed,
    message: passed ? "Users table exists." : `Expected 1 table, got ${count}.`,
    details: { count },
  };
}

export async function table_has_rows(ctx: AssertionContext): Promise<AssertionResult> {
  const result = await ctx.pg.query("SELECT count(*) AS n FROM app.users");
  const count = Number(result.rows[0]?.n ?? 0);
  const passed = count > 0;
  return {
    passed,
    message: passed ? "Table has rows." : "Table is empty.",
    details: { count },
  };
}

import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

export async function five_users_loaded(ctx: AssertionContext): Promise<AssertionResult> {
  const result = await ctx.pg.query("SELECT count(*) AS n FROM app.users");
  const count = Number(result.rows[0]?.n ?? 0);
  const passed = count === 5;
  return {
    passed,
    message: passed ? "Five users loaded." : `Expected 5 users, got ${count}.`,
    details: { count },
  };
}

export async function expected_usernames(ctx: AssertionContext): Promise<AssertionResult> {
  const result = await ctx.pg.query("SELECT username FROM app.users ORDER BY username");
  const names = result.rows.map((r: { username: string }) => r.username);
  const expected = ["alice", "bob", "charlie", "diana", "eve"];
  const passed = JSON.stringify(names) === JSON.stringify(expected);
  return {
    passed,
    message: passed ? "Expected usernames present." : `Expected ${JSON.stringify(expected)}, got ${JSON.stringify(names)}.`,
    details: { names },
  };
}

import { createClient, type ClickHouseClient } from "@clickhouse/client";
import { Pool, type QueryResult } from "pg";

export interface PgClient {
  query: (text: string, params?: unknown[]) => Promise<QueryResult>;
}

const NOOP_PG: PgClient = {
  query: async () => {
    throw new Error("Postgres is not available in this scenario");
  },
};

export interface AssertionContext {
  pg: PgClient;
  clickhouse: ClickHouseClient;
  env: (key: string) => string | undefined;
}

export interface AssertionContextHandle {
  context: AssertionContext;
  close: () => Promise<void>;
}

export function createAssertionContext(
  env: NodeJS.ProcessEnv = process.env,
): AssertionContextHandle {
  const postgresUrl = env.POSTGRES_URL;
  const clickhouseUrl = env.CLICKHOUSE_URL;

  const pgPool = postgresUrl ? new Pool({ connectionString: postgresUrl }) : null;

  const clickhouse = clickhouseUrl
    ? createClient({ url: clickhouseUrl })
    : createClient({ url: "http://localhost:8123" });

  return {
    context: {
      pg: pgPool
        ? { query: (text: string, params?: unknown[]) => pgPool.query(text, params) }
        : NOOP_PG,
      clickhouse,
      env: (key: string) => env[key],
    },
    close: async () => {
      if (pgPool) await pgPool.end();
      await clickhouse.close();
    },
  };
}

